import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_06_01_local.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_06_02_worktrees.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_06_03_cloud.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_06_04_review.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_06_05_git.png",d="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_06_06_decision.png",w=JSON.parse('{"title":"本地改还是云端跑：Codex Cloud、Worktree 与 Code Review 协作指南","description":"Codex 可以在当前工作区直接修改，也可以在独立 Worktree 或 Cloud Environment 中完成任务。三者不是性能档位，而是不同的状态与隔离边界：本地最贴近开发者当前现实，Worktree 隔离并行修改，Cloud 强调可重建和长时间执行。","frontmatter":{"title":"本地改还是云端跑：Codex Cloud、Worktree 与 Code Review 协作指南","description":"Codex 可以在当前工作区直接修改，也可以在独立 Worktree 或 Cloud Environment 中完成任务。三者不是性能档位，而是不同的状态与隔离边界：本地最贴近开发者当前现实，Worktree 隔离并行修改，Cloud 强调可重建和长时间执行。","date":"2026-08-10","topic":"AI 底层学习","section":"OpenAI官方文档解读","readingTime":4,"source":"2026-08-10/ai_codex_official_06_cloud_worktrees_review.md","status":"archived","cover":"/article-assets/2026-08-10/ai_codex_official_06_01_local.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"本地改还是云端跑：Codex Cloud、Worktree 与 Code Review 协作指南"}],["meta",{"property":"og:description","content":"Codex 可以在当前工作区直接修改，也可以在独立 Worktree 或 Cloud Environment 中完成任务。三者不是性能档位，而是不同的状态与隔离边界：本地最贴近开发者当前现实，Worktree 隔离并行修改，Cloud 强调可重建和长时间执行。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_06_01_local.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"本地改还是云端跑：Codex Cloud、Worktree 与 Code Review 协作指南"}],["meta",{"name":"twitter:description","content":"Codex 可以在当前工作区直接修改，也可以在独立 Worktree 或 Cloud Environment 中完成任务。三者不是性能档位，而是不同的状态与隔离边界：本地最贴近开发者当前现实，Worktree 隔离并行修改，Cloud 强调可重建和长时间执行。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_06_01_local.png"}],["meta",{"name":"robots","content":"noindex,follow"}]],"search":false,"prev":false,"next":false},"headers":[],"relativePath":"archive/ai-codex-official-06-cloud-worktrees-review.md","filePath":"archive/ai-codex-official-06-cloud-worktrees-review.md","lastUpdated":null}'),h={name:"archive/ai-codex-official-06-cloud-worktrees-review.md"};function p(_,e,u,m,f,k){return t(),o("div",null,[...e[0]||(e[0]=[r('<blockquote><p>本文为历史归档版本，不再更新。请阅读<a href="/Nav2ArticlesSite/ai/openai-codex-complete-guide">当前版本</a>。</p></blockquote><h1 id="本地改还是云端跑-codex-cloud、worktree-与-code-review-协作指南" tabindex="-1">本地改还是云端跑：Codex Cloud、Worktree 与 Code Review 协作指南 <a class="header-anchor" href="#本地改还是云端跑-codex-cloud、worktree-与-code-review-协作指南" aria-label="Permalink to &quot;本地改还是云端跑：Codex Cloud、Worktree 与 Code Review 协作指南&quot;">​</a></h1><p>Codex 可以在当前工作区直接修改，也可以在独立 Worktree 或 Cloud Environment 中完成任务。三者不是性能档位，而是不同的状态与隔离边界：本地最贴近开发者当前现实，Worktree 隔离并行修改，Cloud 强调可重建和长时间执行。</p><h2 id="一、本地工作区适合连续开发" tabindex="-1">一、本地工作区适合连续开发 <a class="header-anchor" href="#一、本地工作区适合连续开发" aria-label="Permalink to &quot;一、本地工作区适合连续开发&quot;">​</a></h2><h3 id="_1-1-它能够看到未提交状态" tabindex="-1">1.1 它能够看到未提交状态 <a class="header-anchor" href="#_1-1-它能够看到未提交状态" aria-label="Permalink to &quot;1.1 它能够看到未提交状态&quot;">​</a></h3><p>代理读取当前文件、依赖和工具链，适合继续开发者正在进行的工作。与此同时，未提交修改属于用户资产，代理不能静默覆盖、回退或混入无关提交。</p><h3 id="_1-2-本地结果最容易即时验证" tabindex="-1">1.2 本地结果最容易即时验证 <a class="header-anchor" href="#_1-2-本地结果最容易即时验证" aria-label="Permalink to &quot;1.2 本地结果最容易即时验证&quot;">​</a></h3><p>测试、调试器、模拟器和私有工具通常已经存在，反馈速度快。缺点是多个任务共享一个目录时容易互相污染。</p><h3 id="_1-3-开始前必须建立状态基线" tabindex="-1">1.3 开始前必须建立状态基线 <a class="header-anchor" href="#_1-3-开始前必须建立状态基线" aria-label="Permalink to &quot;1.3 开始前必须建立状态基线&quot;">​</a></h3><p>检查当前分支、Git 状态、适用规则和已有失败。没有基线，就无法判断后续差异属于谁。</p><p><img src="'+i+'" alt="图 1：本地工作区从当前状态进入修改与即时验证"></p><h2 id="二、worktree-用目录隔离并行任务" tabindex="-1">二、Worktree 用目录隔离并行任务 <a class="header-anchor" href="#二、worktree-用目录隔离并行任务" aria-label="Permalink to &quot;二、Worktree 用目录隔离并行任务&quot;">​</a></h2><h3 id="_2-1-每个任务拥有独立检出" tabindex="-1">2.1 每个任务拥有独立检出 <a class="header-anchor" href="#_2-1-每个任务拥有独立检出" aria-label="Permalink to &quot;2.1 每个任务拥有独立检出&quot;">​</a></h3><p>Git Worktree 共享对象数据库，却为不同分支提供独立文件目录。一个任务的未完成文件不会被另一个任务直接读取。</p><h3 id="_2-2-隔离不等于没有设计冲突" tabindex="-1">2.2 隔离不等于没有设计冲突 <a class="header-anchor" href="#_2-2-隔离不等于没有设计冲突" aria-label="Permalink to &quot;2.2 隔离不等于没有设计冲突&quot;">​</a></h3><p>两个任务若修改同一接口，合并时仍会发生冲突。分派前要明确文件所有权、公共契约和合并顺序。</p><h3 id="_2-3-验证必须在对应-worktree-中完成" tabindex="-1">2.3 验证必须在对应 Worktree 中完成 <a class="header-anchor" href="#_2-3-验证必须在对应-worktree-中完成" aria-label="Permalink to &quot;2.3 验证必须在对应 Worktree 中完成&quot;">​</a></h3><p>不能用主工作区的旧构建结果证明分支成功。每个工作树都要记录依赖、测试和实际提交。</p><p><img src="'+l+'" alt="图 2：主仓库与多个 Worktree 的并行隔离关系"></p><h2 id="三、cloud-从仓库重建任务现场" tabindex="-1">三、Cloud 从仓库重建任务现场 <a class="header-anchor" href="#三、cloud-从仓库重建任务现场" aria-label="Permalink to &quot;三、Cloud 从仓库重建任务现场&quot;">​</a></h2><h3 id="_3-1-repository-是远程事实入口" tabindex="-1">3.1 Repository 是远程事实入口 <a class="header-anchor" href="#_3-1-repository-是远程事实入口" aria-label="Permalink to &quot;3.1 Repository 是远程事实入口&quot;">​</a></h3><p>Cloud 不会自动获得本机未提交文件。需要执行的代码、配置和说明必须进入连接仓库或明确环境映射。</p><h3 id="_3-2-environment-描述依赖与设置" tabindex="-1">3.2 Environment 描述依赖与设置 <a class="header-anchor" href="#_3-2-environment-描述依赖与设置" aria-label="Permalink to &quot;3.2 Environment 描述依赖与设置&quot;">​</a></h3><p>设置脚本安装依赖、准备工具和缓存。可靠环境应可重复运行，不能依赖某次手工登录留下的隐式状态。</p><h3 id="_3-3-secrets-与代理阶段分离" tabindex="-1">3.3 Secrets 与代理阶段分离 <a class="header-anchor" href="#_3-3-secrets-与代理阶段分离" aria-label="Permalink to &quot;3.3 Secrets 与代理阶段分离&quot;">​</a></h3><p>官方云端安全模型区分设置和代理运行阶段，Secrets 可以只在设置时可用。这样依赖安装能够认证，模型执行阶段不必持续接触秘密。</p><h3 id="_3-4-internet-access-应按域名收口" tabindex="-1">3.4 Internet access 应按域名收口 <a class="header-anchor" href="#_3-4-internet-access-应按域名收口" aria-label="Permalink to &quot;3.4 Internet access 应按域名收口&quot;">​</a></h3><p>云端任务默认不应拥有任意网络。只开放完成任务需要的资源，并把网页与下载内容继续视为不可信输入。</p><p><img src="'+n+'" alt="图 3：仓库、设置脚本、缓存与秘密重建 Cloud Environment"></p><h2 id="四、code-review-是独立质量环节" tabindex="-1">四、Code Review 是独立质量环节 <a class="header-anchor" href="#四、code-review-是独立质量环节" aria-label="Permalink to &quot;四、Code Review 是独立质量环节&quot;">​</a></h2><h3 id="_4-1-review-不等于让代理再写一遍" tabindex="-1">4.1 Review 不等于让代理再写一遍 <a class="header-anchor" href="#_4-1-review-不等于让代理再写一遍" aria-label="Permalink to &quot;4.1 Review 不等于让代理再写一遍&quot;">​</a></h3><p>审查关注正确性、回归、安全、可维护性和测试缺口，应以 Diff 与基线分支为事实。审查者不应在没有证据时重复实现者的假设。</p><h3 id="_4-2-自审与独立审查解决不同问题" tabindex="-1">4.2 自审与独立审查解决不同问题 <a class="header-anchor" href="#_4-2-自审与独立审查解决不同问题" aria-label="Permalink to &quot;4.2 自审与独立审查解决不同问题&quot;">​</a></h3><p>实现线程的自审能发现明显遗漏，独立上下文审查更容易挑战原有方向。高风险修改需要人类负责最终取舍。</p><h3 id="_4-3-发现必须可定位" tabindex="-1">4.3 发现必须可定位 <a class="header-anchor" href="#_4-3-发现必须可定位" aria-label="Permalink to &quot;4.3 发现必须可定位&quot;">​</a></h3><p>每条问题应关联文件、行、风险和触发条件。泛泛而谈的“可能有问题”难以行动，也容易制造 Review 噪声。</p><p><img src="'+c+'" alt="图 4：基线、Diff、自动检查与人工判断组成 Review 链"></p><h2 id="五、git-是跨执行域的事实账本" tabindex="-1">五、Git 是跨执行域的事实账本 <a class="header-anchor" href="#五、git-是跨执行域的事实账本" aria-label="Permalink to &quot;五、Git 是跨执行域的事实账本&quot;">​</a></h2><p>本地、Worktree 和 Cloud 最终都要用 Git 交付。一个提交应围绕可解释结果，包含与目标直接相关的文件和验证证据。推送、创建 Pull Request、合并与发布会影响外部协作者，必须遵循授权边界。</p><p><img src="'+s+'" alt="图 5：不同执行域通过提交与 Pull Request 汇入统一事实链"></p><h2 id="六、windows-与-wsl-按目标工具链选择" tabindex="-1">六、Windows 与 WSL 按目标工具链选择 <a class="header-anchor" href="#六、windows-与-wsl-按目标工具链选择" aria-label="Permalink to &quot;六、Windows 与 WSL 按目标工具链选择&quot;">​</a></h2><p>依赖 Windows SDK、PowerShell 或本机 GUI 的项目适合原生环境；依赖 Bash、容器和 Linux 工具的项目适合 WSL。仓库与构建目录尽量放在主要执行侧，明确路径、大小写、符号链接、可执行位和 CRLF 策略。</p><p>Windows 原生 Sandbox 与 WSL 使用不同平台机制，但目标相同：让命令在受控边界中运行。具体前置条件以当前官方页面为准，不通过关闭系统安全策略来掩盖配置问题。</p><p><img src="'+d+'" alt="图 6：本地、Worktree、Cloud 与 Windows 环境的选择地图"></p><h2 id="七、官方参考资料" tabindex="-1">七、官方参考资料 <a class="header-anchor" href="#七、官方参考资料" aria-label="Permalink to &quot;七、官方参考资料&quot;">​</a></h2><p><a href="https://learn.chatgpt.com/docs/environments/cloud-environment" target="_blank" rel="noreferrer">OpenAI Docs：Cloud environments</a></p><p><a href="https://learn.chatgpt.com/docs/environments/git-worktrees" target="_blank" rel="noreferrer">OpenAI Docs：Worktrees</a></p><p><a href="https://learn.chatgpt.com/docs/code-review" target="_blank" rel="noreferrer">OpenAI Docs：Code review</a></p><p><a href="https://learn.chatgpt.com/docs/windows/windows-app" target="_blank" rel="noreferrer">OpenAI Docs：Windows</a></p>',49)])])}const x=a(h,[["render",p]]);export{w as __pageData,x as default};
